    try {
        scm.addComment(prNumber, summaryFile);
        console.log('✅ Posted test summary as PR/MR comment on feature PR/MR #' + prNumber);
    } catch (e) {
        console.warn('Failed to post PR/MR comment:', e);
    }
}

/** Build a Jira-formatted comment with per-TC table. */
function buildJiraComment(result, automationPrUrl) {
    var status = (result.status || '').toLowerCase();
    var header = status === 'passed'
        ? 'h3. ✅ Mobile Test Automation — All Tests Passed'
        : status === 'blocked_by_human'
        ? 'h3. 🚫 Mobile Test Automation — Blocked'
        : 'h3. ❌ Mobile Test Automation — Tests Failed';

    var lines = [header, '', '*Summary*: ' + (result.summary || result.status) + '\n'];

    var results = result.results || [];
    if (results.length > 0) {
        lines.push('||Test Case||Title||Status||');
        for (var i = 0; i < results.length; i++) {
            var r = results[i];
            var icon = r.status === 'passed' ? '✅' : '❌';
            var notes = r.error ? ' — ' + r.error.substring(0, 200) : '';
            lines.push('|' + r.ticket + '|' + (r.title || '') + '|' + icon + ' ' + r.status + notes + '|');
        }
    }

    if (automationPrUrl) {
        lines.push('', '*Automation PR*: ' + automationPrUrl);
    }

    return lines.join('\n');
}

function removeWipLabel(params, ticketKey) {
    var wipLabel = mobileHelpers.decideWipLabel(params.metadata);
    try { tracker.removeLabel(ticketKey, wipLabel); } catch (e) {}
}

function removeSMTriggerLabel(params, ticketKey) {
    if (!ticketKey) return;
    var customParams = (params.jobParams || params).customParams || {};
    var smTriggerLabel = mobileHelpers.decideSmTriggerLabel(customParams);
    if (smTriggerLabel) {
        try {
            tracker.removeLabel(ticketKey, smTriggerLabel);
            console.log('✅ Removed SM trigger label:', smTriggerLabel);
        } catch (e) {}
    }
}

/** SCM client for the automation repo (config repository or GitHub globals fallback). */
function createAutomationScm(config) {
    return createScmCompat(config, config.repository && config.repository.owner, config.repository && config.repository.repo);
}

/** Step 1: Configure git author in automation repo. */
function configureGitAuthor(config, workingDir) {
    if (!workingDir) {
        return;
    }
    try {
        runInRepo('git config user.name "' + config.git.authorName + '"', workingDir);
        runInRepo('git config user.email "' + config.git.authorEmail + '"', workingDir);
    } catch (e) {
        console.warn('Failed to configure git author:', e);
    }
}

/** Step 2: Get current branch in automation repo (null without workingDir). */
function resolveBranchName(workingDir) {
    if (!workingDir) {
        return null;
    }
    var rawBranch = runInRepo('git branch --show-current', workingDir) || '';
    var branchName = cleanCommandOutput(rawBranch);
    console.log('Automation repo branch:', JSON.stringify(branchName));
    return branchName;
}

/** Step 3: Commit + push test files and create/find the automation PR. Returns PR URL or null. */
function commitAndCreateAutomationPR(ticketKey, ticketSummary, branchName, workingDir, testFilesPath, baseBranch, scm) {
    var automationPrUrl = null;
    if (branchName && workingDir) {
        var commitMessage = sanitizeForShell(ticketKey + ' test: automate ' + ticketSummary);
        var gitResult = performGitOperations(branchName, commitMessage, workingDir, testFilesPath);

        if (gitResult.success) {
            var prTitle = sanitizeForShell(ticketKey + ' ' + ticketSummary);
            var prResult = createAutomationPR(prTitle, branchName, baseBranch, workingDir, scm, ticketKey);
            automationPrUrl = prResult.prUrl;
        } else {
            console.warn('Git operations failed:', gitResult.error);
        }
    }
    return automationPrUrl;
}

/** Inject automation PR URL into feature update markdown if present and not already linked. */
function injectAutomationPrLink(workingDir, ticketKey, automationPrUrl) {
    if (!automationPrUrl) {
        return;
    }
    try {
        var featureUpdateContent = readOutputFile('pr_feature_update.md', workingDir, ticketKey) || '';
        if (featureUpdateContent && featureUpdateContent.indexOf(automationPrUrl) === -1) {
            file_write('outputs/pr_feature_update.md',
                featureUpdateContent + '\n> Automation PR: ' + automationPrUrl + '\n');
        }
    } catch (_) {}
}

/** Step 5: Find the feature PR and update label, automation-PR link and summary comment. */
function updateFeaturePR(featureScm, ticketKey, featureOwner, featureRepo, passed, labelPassed, labelFailed, workingDir, automationPrUrl, result) {
    var featurePR = findFeaturePR(ticketKey, featureScm, featureOwner, featureRepo);
    if (!featurePR) {
        return;
    }
    updateFeaturePRLabelWithScm(featureScm, featurePR.number, passed, labelPassed, labelFailed);
    // Inject automation PR URL into feature update markdown if present
    injectAutomationPrLink(workingDir, ticketKey, automationPrUrl);
    updateFeaturePRBodyWithScm(featureScm, featurePR.number, workingDir, result, ticketKey);
}

/** Step 6: Post the per-TC Jira comment (or the caller-supplied response text). */
function postJiraResultComment(ticketKey, jiraComment, result, automationPrUrl) {
    try {
        var comment = jiraComment || buildJiraComment(result, automationPrUrl);
        if (automationPrUrl && comment.indexOf(automationPrUrl) === -1) {
            comment += '\n\n*Automation PR*: ' + automationPrUrl;
        }
        tracker.postComment(ticketKey, comment);
        console.log('✅ Posted Jira comment');
    } catch (e) {
        console.warn('Failed to post Jira comment:', e);
    }
}

/** Step 7: blocked_by_human — comment, move to Blocked, clean up labels. */
function handleBlockedByHuman(params, ticketKey, result, jiraConfig) {
    try { tracker.postComment(ticketKey, mobileHelpers.buildBlockedComment(result)); } catch (e) {}
    try { tracker.moveToStatus(ticketKey, jiraConfig.statuses.BLOCKED); } catch (e) {}

    removeWipLabel(params, ticketKey);
    removeSMTriggerLabel(params, ticketKey);
    return { success: true, status: 'blocked_by_human', ticketKey: ticketKey };
}

/** Steps 8-9: Move ticket status (stage-label fallback), add AI label, clean up labels. */
function finalizeTicketStatus(params, ticketKey, passed, jiraConfig) {
    try {
        var stageKey = passed ? 'PASSED' : 'FAILED';
        var targetStatus = passed ? jiraConfig.statuses.PASSED : jiraConfig.statuses.FAILED;
        // gh-916: Passed/Failed can be tag-only (restricted ADO workflows) — stage-label fallback.
        var moveResult = tracker.moveToStatusOrMark(ticketKey, targetStatus, stageKey);
        if (moveResult.moved || moveResult.marked) {
            console.log('✅ Moved', ticketKey, 'to', targetStatus);
        }
    } catch (e) {
        console.warn('Failed to move ticket status:', e);
    }

    // Step 9: Add AI label
    try {
        tracker.addLabel(ticketKey, LABELS.AI_TEST_AUTOMATION);
    } catch (e) {
        console.warn('Failed to add AI label:', e);
    }

    removeWipLabel(params, ticketKey);
    removeSMTriggerLabel(params, ticketKey);
}

function loadConfigSafe(params) {
    try { return configLoader.loadProjectConfig(params.jobParams || params); } catch (e) { return null; }
}

function action(params) {
    // Early tracker so the catch-path can still comment if config loading fails
    tracker = trackersModule.createTracker(loadConfigSafe(params), (params.jobParams || params).customParams || {});
    try {
        var ticketKey = params.ticket.key;
        var ticketSummary = params.ticket.fields ? params.ticket.fields.summary : ticketKey;
        var jiraComment = params.response || '';
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        tracker = trackersModule.createTracker(config, (params.jobParams || params).customParams || {});
        var jiraConfig = config.jira;
        var automationScm = createAutomationScm(config);
        var workingDir = config.workingDir;

        var customParams = (params.jobParams || params).customParams || {};
        var featureTarget = mobileHelpers.decideFeatureTarget(customParams);
        var featureOwner = featureTarget.owner;
        var featureRepo = featureTarget.repo;
        var featureScm = (featureOwner && featureRepo) ? createScmCompat(config, featureOwner, featureRepo) : null;

        var labels = mobileHelpers.decideLabels(customParams);
        var labelPassed = labels.labelPassed;
        var labelFailed = labels.labelFailed;
        var testFilesPath = labels.testFilesPath;

        console.log('=== Processing mobile test automation results for', ticketKey, '===');

        // Step 1: Configure git author in automation repo
        configureGitAuthor(config, workingDir);

        // Step 2: Get current branch in automation repo
        var branchName = resolveBranchName(workingDir);

        // Step 2b: If mandatory outputs are missing, attempt one resume run before committing.
        // This handles the case where the agent ran out of context or was interrupted
        // before writing outputs/test_automation_result.json and friends.
        var resumed = attemptResumeIfOutputsMissing(ticketKey, workingDir);
        if (resumed) {
            console.log('Resume run completed — re-checking outputs before proceeding.');
        }

        // Step 3: Commit + push + create automation PR (ALWAYS — don't lose agent's work)
        var automationPrUrl = commitAndCreateAutomationPR(
            ticketKey, ticketSummary, branchName, workingDir, testFilesPath, config.git.baseBranch, automationScm);

        // Step 4: Read structured result (fallback: workspace root → automation repo outputs)
        var result = readResultJson(workingDir, ticketKey);
        if (!result) {
            console.warn('No test_automation_result.json found — posting error to Jira but keeping git work');
            try {
                tracker.postComment(ticketKey, mobileHelpers.buildMissingResultComment(resumed, automationPrUrl));
            } catch (e) { console.warn('Failed to post error Jira comment:', e); }
            return { success: false, error: 'No test result JSON found', automationPrUrl: automationPrUrl };
        }

        var outcome = mobileHelpers.parseOutcome(result);
        var blockedByHuman = outcome.blockedByHuman;

        // Check for a11y structural warnings — log but do NOT override test status.
        // A11y warnings are informational; Maestro tests that pass → tests_passed label.
        var a11yWarnings = mobileHelpers.hasA11yWarnings(result);
        if (a11yWarnings && outcome.passed) {
            console.log('⚠️ Maestro tests passed with a11y structural warnings (informational — not overriding status)');
        }

        // Step 5: Find feature PR and update it
        if (featureScm && !blockedByHuman) {
            updateFeaturePR(featureScm, ticketKey, featureOwner, featureRepo, outcome.passed,
                labelPassed, labelFailed, workingDir, automationPrUrl, result);
        }

        // Step 6: Post Jira comment
        postJiraResultComment(ticketKey, jiraComment, result, automationPrUrl);

        // Step 7: Handle blocked_by_human
        if (blockedByHuman) {
            return handleBlockedByHuman(params, ticketKey, result, jiraConfig);
        }

        // Steps 8-9: Move ticket status, add AI label, clean up labels
        finalizeTicketStatus(params, ticketKey, outcome.passed, jiraConfig);

        console.log('✅ Mobile test automation workflow complete:', outcome.passed ? 'PASSED' : 'FAILED');

        return {
            success: true,
            status: result.status,
            ticketKey: ticketKey,
            automationPrUrl: automationPrUrl
        };

    } catch (error) {
        console.error('❌ Error in postMobileTestAutomationResults:', error);
        try {
            tracker.postComment(params.ticket.key, mobileHelpers.buildErrorComment(error));
        } catch (e) {}
        removeSMTriggerLabel(params, params.ticket && params.ticket.key);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        // gh-1083 test surface: direct github-globals label path (kept for
        // flows without the SCM abstraction — characterization-tested).
        updateFeaturePRLabel: updateFeaturePRLabel
    };
}

/**
 * Pure helpers for js/preCliMobileTestAutomationSetup.js (gh-1034).
 *
 * Parse/decide/build logic extracted from action(), downloadBitriseApp()
 * and installAppOnSimulator() so all three shrink below the CRAP threshold.
 * Every function here is side-effect free (console/tracker/SCM/file calls
 * stay in the caller, in the original order) and every returned string or
 * decision must stay byte-identical to the original inline logic.
 */

/**
 * Successful Bitrise builds (status=1 or status_text 'success').
 * Empty-safe: a null/absent builds array yields an empty list.
 */
function decideSuccessfulBuilds(builds) {
    var success = [];
    var list = builds || [];
    for (var i = 0; i < list.length; i++) {
        if (list[i].status === 1 || list[i].status_text === 'success') {
            success.push(list[i]);
        }
    }
    return success;
}

/**
 * Branch-filter decision over successful builds.
 * Returns { builds, matched }: when a branch is given and at least one
 * build's commit message mentions it, builds is the matched subset and
 * matched is true; otherwise builds is the input list unchanged.
 */
function decideBranchBuilds(successBuilds, branch) {
    var result = { builds: successBuilds, matched: false };
    if (branch && successBuilds.length > 0) {
        var matched = [];
        for (var i = 0; i < successBuilds.length; i++) {
            var b = successBuilds[i];
            var msg = b.commit_message || b.original_build_params_commit_message || '';
            if (msg.indexOf(branch) !== -1) {
                matched.push(b);
            }
        }
        if (matched.length > 0) {
            result.builds = matched;
            result.matched = true;
        }
    }
    return result;
}

/**
 * First build's slug/number, or throw the canonical "no successful builds"
 * error the download step has always produced.
 */
function decideBuildSlug(builds, workflowId) {
    if (!builds || builds.length === 0) {
        throw new Error('No successful ' + workflowId +
            ' builds found. Trigger a build first, then re-run this automation.');
    }
    return { slug: builds[0].slug, buildNumber: builds[0].build_number };
}

/** Warning lines listing up to 5 available builds (for the no-match warn). */
function formatBuildsWarningList(successBuilds) {
    var lines = [];
    for (var si = 0; si < Math.min(successBuilds.length, 5); si++) {
        lines.push('   #' + successBuilds[si].build_number + ': "' +
            (successBuilds[si].commit_message || '').substring(0, 80) + '"');
    }
    return lines;
}

/**
 * Pick the app artifact from a build's artifact list: the first title
 * containing .zip/.app/simulator, else the first artifact, else null
 * (only possible when the list itself is empty).
 */
function decideAppArtifact(artifactList) {
    var list = artifactList || [];
    for (var i = 0; i < list.length; i++) {
        var t = (list[i].title || '').toLowerCase();
        if (t.indexOf('.zip') !== -1 || t.indexOf('.app') !== -1 || t.indexOf('simulator') !== -1) {
            return list[i];
        }
    }
    return list.length > 0 ? list[0] : null;
}

/** First real .app path from a `find ... -name "*.app"` output (no .dSYM). */
function parseFindAppResult(findResult) {
    if (!findResult) return null;
    var lines = findResult.split('\n');
    for (var i = 0; i < lines.length; i++) {
        var l = lines[i].trim();
        if (l.length > 0 && l.indexOf('.dSYM') === -1) {
            return l;
        }
    }
    return null;
}

/** app_info.md body — byte-identical to the original inline builder. */
function buildAppInfoMarkdown(workflowId, buildSlug, artifactTitle, branch, appPath, appDir) {
    var lines = [];
    lines.push('# iOS App Build Info\n');
    lines.push('The iOS simulator app has been downloaded from Bitrise and is ready to use.\n');
    lines.push('| Field | Value |');
    lines.push('|-------|-------|');
    lines.push('| Bitrise Workflow | ' + workflowId + ' |');
    lines.push('| Build Slug | ' + buildSlug + ' |');
    lines.push('| Artifact | ' + artifactTitle + ' |');
    if (branch) lines.push('| Branch | ' + branch + ' |');
    if (appPath) {
        lines.push('| App Path | `' + appPath + '` |');
        lines.push('\n## How to use\n');
        lines.push('Set `APP_PATH` environment variable or pass `--app-path` to Maestro:\n');
        lines.push('```bash');
        lines.push('export APP_PATH="' + appPath + '"');
        lines.push('maestro test --app-path "$APP_PATH" src/flows/...');
        lines.push('```');
    } else {
        lines.push('| App Dir | `' + appDir + '` |');
        lines.push('\n> ⚠️ Unzipped to `' + appDir + '` — locate the `.app` bundle manually.');
    }
    return lines;
}

/**
 * Environment-specific build config resolution.
 * Returns { active, environment, buildConfig, envConfig }: when the
 * bitriseBuild config carries an entry for testEnvironment, buildConfig is
 * rebuilt with the env-specific workflowId override and active is true.
 */
function resolveEnvironmentBuildConfig(bitriseBuild, testEnvironment) {
    var result = {
        active: false,
        environment: testEnvironment,
        buildConfig: bitriseBuild,
        envConfig: null
    };
    if (bitriseBuild.environments && bitriseBuild.environments[testEnvironment]) {
        var envConfig = bitriseBuild.environments[testEnvironment];
        result.active = true;
        result.envConfig = envConfig;
        result.buildConfig = {
            appSlug: bitriseBuild.appSlug,
            workflowId: envConfig.workflowId || bitriseBuild.workflowId
        };
    }
    return result;
}

/** environment.md body — byte-identical to the original inline builder. */
function buildEnvironmentMarkdown(testEnvironment, workflowId, envConfig) {
    var envLines = [];
    envLines.push('# Test Environment: ' + testEnvironment.toUpperCase() + '\n');
    envLines.push('| Setting | Value |');
    envLines.push('|---------|-------|');
    envLines.push('| Environment | ' + testEnvironment + ' |');
    envLines.push('| Bitrise Workflow | ' + workflowId + ' |');
    if (envConfig.appId) envLines.push('| APP_ID | `' + envConfig.appId + '` |');
    envLines.push('\n## Credentials\n');
    envLines.push('Login credentials are available as environment variables:');
    envLines.push('- `' + (envConfig.userEnvVar || 'TEST_USER_EMAIL') + '` — user email');
    envLines.push('- `' + (envConfig.passwordEnvVar || 'TEST_USER_PASSWORD') + '` — password');
    envLines.push('- `' + (envConfig.pinEnvVar || 'TEST_USER_PIN') + '` — PIN code');
    envLines.push('\nUse these env var names in Maestro flows for `inputText` steps.');
    return envLines;
}

/** Bundle id from the environment config, or null when not configured. */
function decideAppId(bitriseBuild, testEnvironment) {
    if (bitriseBuild && bitriseBuild.environments) {
        var ec = bitriseBuild.environments[testEnvironment];
        if (ec && ec.appId) return ec.appId;
    }
    return null;
}

/** Default mobile bundle id when the caller did not provide one. */
function defaultAppId(appId) {
    return appId || 'com.example.internal.business.app';
