            { status: 'passed' },
            { status: 'error' },
            { status: 'failed' },
            { status: 'skipped' },
            { status: 'passed' },
            { status: 'written' }
        ]);
        assert.deepEqual(counts, { passed: 2, failed: 2, skipped: 1 });
    });

